"""Extended original CC0 vectors for the non-biology discipline packs."""
from __future__ import annotations
import math

INK='#395B70';BLUE='#84B7C8';PALE='#DFEDF1';TEAL='#79A99A';GOLD='#D5AA6C';RED='#C67F76';WHITE='#FFFFFF'

def tag(name,**attrs):
    import html
    return '<'+name+''.join(' '+k.replace('_','-')+'="'+html.escape(str(v),quote=True)+'"' for k,v in attrs.items())+'/>'

def path(d,fill='none',stroke=INK,sw=2):
    # Compact artwork often calls path(d, color, width). Interpret that as a
    # stroked line; pale/white are the two intentionally filled exceptions.
    if isinstance(stroke,(int,float)) and isinstance(fill,str):
        if fill==PALE:
            stroke,sw=INK,stroke
        elif fill==WHITE:
            fill,stroke,sw='none',WHITE,stroke
        else:
            fill,stroke,sw='none',fill,stroke
    return tag('path',d=d,fill=fill,stroke=stroke,stroke_width=sw,stroke_linecap='round',stroke_linejoin='round')

def rect(x,y,w,h,fill=PALE,rx=2):
    return tag('rect',x=x,y=y,width=w,height=h,fill=fill,rx=rx,stroke=INK,stroke_width=2)

def circle(x,y,r,fill=PALE,stroke=INK):
    return tag('circle',cx=x,cy=y,r=r,fill=fill,stroke=stroke,stroke_width=2)

def ellipse(x,y,rx,ry,fill=PALE,stroke=INK):
    return tag('ellipse',cx=x,cy=y,rx=rx,ry=ry,fill=fill,stroke=stroke,stroke_width=2)

def line(x,y,u,v,color=INK,sw=2):
    return tag('line',x1=x,y1=y,x2=u,y2=v,stroke=color,stroke_width=sw,stroke_linecap='round')

def polygon(points,fill=PALE,stroke=INK,sw=2):
    return tag('polygon',points=points,fill=fill,stroke=stroke,stroke_width=sw,stroke_linejoin='round')

def text(value,x,y,size=12,fill=INK,anchor='middle'):
    import html
    return '<text x="'+str(x)+'" y="'+str(y)+'" fill="'+fill+'" font-family="Arial" font-size="'+str(size)+'" font-weight="700" text-anchor="'+anchor+'">'+html.escape(value)+'</text>'

def group(body,transform):
    return '<g transform="'+transform+'">'+body+'</g>'

def arrow(x,y,u,v,color=INK,sw=2,head=7):
    a=math.atan2(v-y,u-x)
    q1=(u-head*math.cos(a-math.pi/7),v-head*math.sin(a-math.pi/7))
    q2=(u-head*math.cos(a+math.pi/7),v-head*math.sin(a+math.pi/7))
    return line(x,y,u,v,color,sw)+line(u,v,*q1,color,sw)+line(u,v,*q2,color,sw)

def dashed(x,y,u,v,color=INK,sw=2,segments=5):
    dx=(u-x)/segments;dy=(v-y)/segments
    return ''.join(line(x+dx*(i+.15),y+dy*(i+.15),x+dx*(i+.72),y+dy*(i+.72),color,sw) for i in range(segments))

def chain(points,color=INK,sw=2,fill='none'):
    return path('M '+' L '.join(f'{x:.2f} {y:.2f}' for x,y in points),fill,color,sw)

def curve(d,color=INK,sw=2,fill='none'):
    return path(d,fill,color,sw)

def dots(items,r=4,fill=BLUE):
    return ''.join(circle(x,y,r,fill) for x,y in items)

def cylinder(x,y,w,h,fill=PALE,accent=BLUE):
    return rect(x,y,w,h,fill,rx=w/5)+ellipse(x+w/2,y,w/2,w/8,accent)+ellipse(x+w/2,y+h,w/2,w/8,fill)

def gear(cx,cy,r,teeth,fill=TEAL):
    points=[]
    for n in range(teeth*2):
        a=n*math.pi/teeth;radius=r if n%2==0 else r-6
        points.append((cx+radius*math.cos(a),cy+radius*math.sin(a)))
    return polygon(' '.join(f'{x:.2f},{y:.2f}' for x,y in points),fill)+circle(cx,cy,r*.32,WHITE)

def screen(x,y,w,h,accent=BLUE):
    return rect(x,y,w,h,'#FFFFFF',2)+rect(x+5,y+5,w-10,h-10,accent,1)+line(x+w/2,y+h,x+w/2,y+h+9,INK,4)+line(x+w/2-12,y+h+9,x+w/2+12,y+h+9,INK,3)

def flame(x,y,scale=1):
    return group(path(f'M{x} {y-22} C{x+18} {y-6} {x+12} {y+10} {x} {y+10} C{x-12} {y+10} {x-18} {y-6} {x} {y-22} Z',RED),f'translate({x} {y}) scale({scale}) translate({-x} {-y})')

